// PROTOTYP 2026-10-26 — provleken Sal's Saloon ur packages/server/scripts/spelkort.ts (spelkortDoc), 77 rader.
window.LEK = {"n":77,"fields":["title","typ","raritet","body","antal"],"rows":[{"id":"juice-em-up","fields":{"title":"Juice em' up!","typ":"Playcard","raritet":"Diamant","body":"Välj två andra spelare. De blandar en shot till varann","antal":1}},{"id":"sals-saloon","fields":{"title":"Sal's Saloon","typ":"Location","raritet":"Guld","body":"Saloonen öppnar! \nLägg upp ett shopkort per spelare som går in. I turordning från dig: slå tärningen – slaget plus ditt guld är din budget. Köp ett eller flera kort eller avstå","antal":2}},{"id":"dustydice-casino","fields":{"title":"DustyDice Casino","typ":"Location","raritet":"Guld","body":"Välkommen till kasinot!\n\nAlla annonserar sin insats (1–10 klunkar) och slår sedan en tärning samtidigt.\n5–6: dela ut dubbla insatsen.\n1–4: drick din insats.\n\n🏴‍☠️ - Här går det att sälja dina stöldgods","antal":2}},{"id":"free-for-all","fields":{"title":"Free for all","typ":"Effect","raritet":"Special","body":"Era stöldgods är i fara! Så länge effekten ligger får ni sno varandras stöldgodskort. Blir du påkommen (någon säger till medan du snor) dricker du kortets värde i klunkar","antal":1}},{"id":"duel-koppar","fields":{"title":"Duel","typ":"Playcard","raritet":"Koppar","body":"Utmana en spelare på duell. Förloraren dricker 3","antal":4}},{"id":"duel-silver","fields":{"title":"Duel","typ":"Playcard","raritet":"Silver","body":"Utmana en spelare på duell. Förloraren dricker 5","antal":4}},{"id":"duel-guld","fields":{"title":"Duel","typ":"Playcard","raritet":"Guld","body":"Utmana en spelare på duell. Förloraren dricker 7","antal":2}},{"id":"duel-diamant","fields":{"title":"Duel","typ":"Playcard","raritet":"Diamant","body":"Utmana en spelare på duell. Vinnaren blandar en shot till förloraren","antal":1}},{"id":"saddle-pals","fields":{"title":"Saddle Pals","typ":"Playcard","raritet":"Diamant","body":"Välj en annan spelare. Ni är allierade resten av spelet.\nNär en av er får klunkar dricker BÅDA fullt.\nBåda delar ut +2 klunkar","antal":1}},{"id":"standoff","fields":{"title":"Standoff","typ":"Event","raritet":"Diamant","body":"Dela upp er i två lag efter hur ni sitter. Öppna en ny enhet och duellera lag mot lag – laget som druckit upp sist förlorar. Vinnarna går raka vägen till Sal's Saloon","antal":1}},{"id":"zorros-here","fields":{"title":"Zorro's here!","typ":"Event","raritet":"Guld","body":"Zorro är här för att stoppa er. Slå en tärning var. Slår MINST HÄLFTEN 4 eller mer kommer ni undan. Annars beslagtar Zorro allt stöldgods och alla dricker 5","antal":2}},{"id":"the-heist","fields":{"title":"The Heist","typ":"Event","raritet":"Silver","body":"Ni ska försöka råna ett bankvalv. \n\nRåna valvet: 3 guld + allt i The Bank. Ta upp till 2 kompanjoner och dela vinsten.\nSlå en tärning var per omgång. 4+ av någon = omgången lyckas. Tre i rad = valvet är ert.\nMiss: alla dricker 5","antal":3}},{"id":"stolen-goods-koppar","fields":{"title":"Stolen Goods","typ":"Playcard","raritet":"Koppar","body":"1 värdesak! Värde 1. Säljs för 1 guld. Böter 1 klunk.\n\nDessa går att säljas på två sätt. \n1. Besök en plats där det står att man kan sälja dem \n2. Bränn din runda och slå 5 eller 6, misslyckas du måste du slänga 1 stöldgods av ditt val\n\nVar försiktig för det är enkelt att bli av med dessa","antal":4}},{"id":"stolen-goods-silver","fields":{"title":"Stolen Goods","typ":"Playcard","raritet":"Silver","body":"2 värdesaker! Värde 2. Säljs för 2 guld. Böter 2 klunkar.\n\nDessa går att säljas på två sätt. \n1. Besök en plats där det står att man kan sälja dem \n2. Bränn din runda och slå 5 eller 6, misslyckas du måste du slänga 1 stöldgods av ditt val\n\nVar försiktig för det är enkelt att bli av med dessa","antal":4}},{"id":"stolen-goods-guld","fields":{"title":"Stolen Goods","typ":"Playcard","raritet":"Guld","body":"3 värdesaker! Värde 3. Säljs för 3 guld. Böter 3 klunkar.\n\nDessa går att säljas på två sätt. \n1. Besök en plats där det står att man kan sälja dem \n2. Bränn din runda och slå 5 eller 6, misslyckas du måste du slänga 1 stöldgods av ditt val\n\nVar försiktig för det är enkelt att bli av med dessa","antal":2}},{"id":"the-alley","fields":{"title":"The Alley","typ":"Location","raritet":"Silver","body":"I gränden kan man stöta på mycket skumma typer, slå en tärning.\n1-2: Ajdå! Du stöter på en skum typ och blir skjuten, drick 5\n3-4: Lokala alkisen bjussar på en jäkel, dela ut 5\n5-6: Du träffar Hasse som visar dig bakvägen in till Sal's Saloon","antal":4}},{"id":"sheriffs-check","fields":{"title":"Sheriff's Check","typ":"Playcard","raritet":"Koppar","body":"Har du stöldgods: annonsera två siffror och slå. Slår du en av siffrorna du sa så tar sheriffen allt ditt stöldgods.\nHar du inget: tjalla på någon som har. Den annonserar två egna siffror och slår i stället","antal":4}},{"id":"deflect","fields":{"title":"Deflect","typ":"Trap+","raritet":"Guld","body":"Klunkarna riktade mot dig går istället till dina grannar, båda dricker full mängd","antal":2}},{"id":"reflection","fields":{"title":"Reflection","typ":"Trap+","raritet":"Silver","body":"Tillbakakaka gubbjävel, ge tillbaka klunkarna till den som delade ut dem","antal":4}},{"id":"double-down","fields":{"title":"Double Down","typ":"Trap+","raritet":"Diamant","body":"Den som delar ut klunkar till dig får tillbaka dem och tar dessutom en shot som en annan spelare väljer","antal":1}},{"id":"final-shootout","fields":{"title":"Final Shootout","typ":"Playcard","raritet":"Special","body":"Sista kortet i leken, gå varvet runt och spela en stor duell mot varann, vinnaren donerar en del av sin dryck till Sal's Concucktion™ och slinker undan. Repetera tills det bara finns en spelare kvar, denna spelare måste ta sig an Sal's Concucktion™. \nKaraktärer och shopkort från Sal's Saloon gäller här – inget annat","antal":1}},{"id":"the-bank","fields":{"title":"The Bank","typ":"Location","raritet":"Guld","body":"Du kan sätta in ditt guld i banken. Bankat guld räknas med när du handlar i saloonen, men kan gå förlorat i The Heist","antal":2}},{"id":"cactus-hugger","fields":{"title":"Cactus Hugger","typ":"Playcard","raritet":"Koppar","body":"Dålig idé att krama en kaktus, Drick 2","antal":2}},{"id":"snake-in-the-boot","fields":{"title":"Snake in the boot","typ":"Playcard","raritet":"Silver","body":"Orm i stöveln! Drick 4","antal":4}},{"id":"buckaroos-backfire","fields":{"title":"Buckaroo's Backfire","typ":"Playcard","raritet":"Guld","body":"Hästen sparkar skiten ur dig! Drick 6","antal":2}},{"id":"shoot-from-the-hip","fields":{"title":"Shoot from the hip","typ":"Playcard","raritet":"Koppar","body":"Lyckoträff från höften. Dela ut 2","antal":2}},{"id":"quickdraw","fields":{"title":"Quickdraw","typ":"Playcard","raritet":"Silver","body":"Ingen drar snabbare än dig. Dela ut 4","antal":4}},{"id":"bullseye","fields":{"title":"Bullseye","typ":"Playcard","raritet":"Guld","body":"Rakt mellan ögonen. Dela ut 6","antal":2}},{"id":"drunken-gambler","fields":{"title":"Drunken Gambler","typ":"Character","raritet":"Karaktär","body":"Du dricker alltid 1 klunk mer än kortet säger. När du delar ut SHOTS delar du ut dubbelt så många","antal":1}},{"id":"lucky-luuk","fields":{"title":"Lucky Luuk","typ":"Character","raritet":"Karaktär","body":"Du har +1 i dueller","antal":1}},{"id":"sore-loser-lou","fields":{"title":"Sore Loser Lou","typ":"Character","raritet":"Karaktär","body":"I dueller räknas både 1 och 6 som att du slår 6","antal":1}},{"id":"big-busta","fields":{"title":"Big Busta","typ":"Character","raritet":"Karaktär","body":"Du delar ut och dricker 2 extra klunkar","antal":1}},{"id":"lightweight-lenny","fields":{"title":"Lightweight Lenny","typ":"Character","raritet":"Karaktär","body":"Du delar ut och dricker 1 klunk mindre","antal":1}},{"id":"goldrush-gus","fields":{"title":"Goldrush Gus","typ":"Character","raritet":"Karaktär","body":"Varje gång du säljer stöldgods får du 1 guld extra","antal":1}},{"id":"lightweight-lisa","fields":{"title":"Lightweight Lisa","typ":"Character","raritet":"Karaktär","body":"Du delar ut och dricker 1 klunk mindre","antal":1}},{"id":"beermageddon","fields":{"title":"Beermageddon","typ":"Shopcard","raritet":"Diamant","body":"Alla andra spelare dricker lika många klunkar varje gång du dricker, resten av spelet","antal":1}},{"id":"silver-bullet","fields":{"title":"Silver bullet","typ":"Shopcard","raritet":"Koppar","body":"\"+1\" i en duel","antal":2}},{"id":"to-the-brim","fields":{"title":"To the brim!","typ":"Shopcard","raritet":"Koppar","body":"Nästa gång du delar ut klunkar delar du ut 2 extra","antal":2}},{"id":"faster-than-your-own-shadow","fields":{"title":"Faster Than Your Own Shadow","typ":"Shopcard","raritet":"Guld","body":"Vinn en duell automatiskt","antal":2}},{"id":"lazy-lloyd","fields":{"title":"Lazy Lloyd","typ":"Character","raritet":"Karaktär","body":"Du kan när som helst be valfri spelare hämta ny dryck åt dig – vägrar den dricker den 2. En gång per spel kan du låta en annan spelare ta dina klunkar.","antal":1}},{"id":"poisoned","fields":{"title":"Poisoned","typ":"Playcard","raritet":"Silver","body":"Lägg kortet framför en annan spelare. Den har -1 i dueller under SIN NÄSTA TUR. Sedan slängs kortet","antal":2}},{"id":"jagerbomb","fields":{"title":"Jägerbomb","typ":"Shopcard","raritet":"Silver","body":"Blanda in kortet i spelleken upp och ner. Den som drar det dricker 6.","antal":2}},{"id":"cholera","fields":{"title":"Cholera","typ":"Shopcard","raritet":"Diamant","body":"Välj en spelare. Den har ett varv på sig att avsluta sin dryck. Misslyckas den tar den också en shot","antal":1}},{"id":"tumbleweed-town","fields":{"title":"Tumbleweed Town","typ":"Effect","raritet":"Special","body":"Stan är tyst. Ingen får prata under sin egen tur – den som gör det dricker 2.","antal":1}},{"id":"rolling-stone","fields":{"title":"Rolling Stone","typ":"Playcard","raritet":"Diamant","body":"Stoppa bumlingen och få en belöning! Detta är ett \"växande\" kort, \nDela ut 1 klunk och passa kortet medsols. Nästa delar ut 2, sedan 3, upp till 8. Kedjan kan inte brytas. Den som dricker de sista 8 får 1 guld.","antal":1}},{"id":"hit-by-tumbleweed","fields":{"title":"Hit by Tumbleweed","typ":"Playcard","raritet":"Koppar","body":"Se upp för fan! Drick 2","antal":2}},{"id":"russian-roulette","fields":{"title":"Russian Roulette","typ":"Shopcard","raritet":"Guld","body":"Annonsera lågt (1–3) eller högt (4–6) och slå en tärning.\nRätt: dela ut 12. Fel: drick 6.","antal":2}},{"id":"shots-fired","fields":{"title":"Shots Fired","typ":"Shopcard","raritet":"Diamant","body":"Annonsera lågt (1–3) eller högt (4–6) och slå en tärning.\nRätt: dela ut 2 shots till en spelare. Fel: ta 1 shot","antal":1}},{"id":"lucky-draw","fields":{"title":"Lucky Draw","typ":"Playcard","raritet":"Koppar","body":"Plötsligt händer det. Dela ut 2","antal":2}},{"id":"master-of-the-jukebox","fields":{"title":"Master of the Jukebox","typ":"Shopcard","raritet":"Koppar","body":"Du bestämmer musiken resten av spelet. En gång per varv kan du peka på en spelare som måste ge namnet på artisten – annars dricker den 3.","antal":2}},{"id":"luck-of-the-draw","fields":{"title":"Luck of the Draw","typ":"Playcard","raritet":"Guld","body":"Du får ett gratis shopkort. Slå en tärning för att bestämma vilket.\n1-2: Koppar\n3-4: Silver\n5: Guld\n6: Diamant","antal":2}},{"id":"high-noon","fields":{"title":"High Noon","typ":"Shopcard","raritet":"Guld","body":"Lägg detta kort och säg \"High Noon\", sist av medspelarna att dra fram sina fingerguns dricker 6","antal":2}},{"id":"shots-shots-shots","fields":{"title":"SHOTS SHOTS SHOTS","typ":"Shopcard","raritet":"Diamant","body":"Alla tar en shot. Du väljer en spelare som tar en dubbel","antal":1}},{"id":"the-giver","fields":{"title":"The Giver","typ":"Shopcard","raritet":"Guld","body":"Alla andra dricker 5","antal":2}},{"id":"fact-or-fable","fields":{"title":"Fact or Fable","typ":"Playcard","raritet":"Guld","body":"Säg ett påstående om dig själv, folk gissar sant eller falskt, förlorarna dricker 6","antal":2}},{"id":"howdy-neighbour","fields":{"title":"Howdy Neighbour","typ":"Shopcard","raritet":"Guld","body":"Välj en spelare. Den slår en tärning – den och båda dess grannar dricker så många klunkar.","antal":2}},{"id":"reverse","fields":{"title":"Reverse","typ":"Effect","raritet":"Special","body":"Spelriktningen byts – ni spelar motsols. Och allt byter håll: ska du DRICKA delar du i stället UT, ska du DELA UT dricker du själv.\nTrap och Debuff påverkas inte.","antal":1}},{"id":"hammer-time","fields":{"title":"Hammer Time!","typ":"Effect","raritet":"Special","body":"Alla klunkar är +1","antal":1}},{"id":"double-up","fields":{"title":"Double Up!","typ":"Effect","raritet":"Special","body":"Spelarna får dra två kort per runda","antal":1}},{"id":"wild-west","fields":{"title":"Wild West","typ":"Effect","raritet":"Special","body":"Fritt fram att satsa 1–5 klunkar och utmana vem du vill på duell, när du vill","antal":1}},{"id":"four-sure-fred","fields":{"title":"Four-Sure Fred","typ":"Character","raritet":"Karaktär","body":"I DUELLER: \n1–3 räknas som 1 och du dricker 3 klunkar\n4–6 räknas som 6\n\nÖvriga tärningsslag slår du som vanligt","antal":1}},{"id":"trapster-trevor","fields":{"title":"Trapster Trevor","typ":"Character","raritet":"Karaktär","body":"När en av dina Traps utlöses kan du slå en tärning. \nSlår du 1–3 behöver du inte slänga kortet – det kan användas en gång till.","antal":1}},{"id":"devastating-defeat","fields":{"title":"Devastating Defeat","typ":"Trap-","raritet":"Silver","body":"Förlorar du en duell dricker du +4","antal":4}},{"id":"misfire","fields":{"title":"Misfire","typ":"Trap-","raritet":"Guld","body":"Du har -2 i din nästa duell","antal":2}},{"id":"minefield","fields":{"title":"Minefield","typ":"Trap-","raritet":"Diamant","body":"När någon delar ut klunkar till dig, slå två tärningar. Två lika: du klarar dig och dricker som vanligt. Annars adderas tärningarna till antalet","antal":1}},{"id":"mexican-standoff","fields":{"title":"Mexican Standoff","typ":"Shopcard","raritet":"Silver","body":"Välj tre spelare som duellerar mot varandra. Alla slår, de två lägsta förlorar. Vinnaren delar ut 5 till en av förlorarna","antal":2}},{"id":"selective-drawing","fields":{"title":"Selective Drawing","typ":"Shopcard","raritet":"Silver","body":"På din tur: titta på de tre översta korten, välj ett och lägg tillbaka de andra i valfri ordning på toppen. Detta förbrukar din tur","antal":2}},{"id":"saloon-brawl","fields":{"title":"Saloon Brawl","typ":"Event","raritet":"Koppar","body":"Slagsmål bryter ut! Alla duellerar samtidigt mot sin vänstra granne. Förlorarna dricker 4","antal":4}},{"id":"cattle-stampede","fields":{"title":"Cattle Stampede","typ":"Event","raritet":"Silver","body":"Boskapen skenar genom stan! Alla slår en tärning. Alla som slår 1–3 trampas ner och dricker 4. Den som slår högst delar ut 4","antal":3}},{"id":"wanted-poster","fields":{"title":"Wanted Poster","typ":"Event","raritet":"Silver","body":"Sheriffen spikar upp en efterlysning. Spelaren med mest stöldgods är efterlyst – alla andra med stöldgods delar ut 2 klunkar var till den efterlysta. Har ingen stöldgods är det du","antal":3}},{"id":"last-train-out-of-town","fields":{"title":"Last Train Out of Town","typ":"Event","raritet":"Guld","body":"Tåget går! Slå en tärning i turordning från dig. Första spelaren som slår 6 hinner ombord och slipper undan. Slår ingen 6 på ett varv dricker alla 5","antal":2}},{"id":"dust-storm","fields":{"title":"Dust Storm","typ":"Event","raritet":"Diamant","body":"Sandstormen sveper in. Lägg alla Traps på bordet, blanda dem och dela ut dem slumpmässigt igen. Alla dricker 2 medan ni gör det","antal":1}},{"id":"sundown","fields":{"title":"Sundown","typ":"Effect","raritet":"Special","body":"Solen går ner. Alla klunkar är -1, men aldrig mindre än 1","antal":1}},{"id":"bounty-season","fields":{"title":"Bounty Season","typ":"Effect","raritet":"Special","body":"Alla stöldgods är dubbelt värda vid försäljning","antal":1}},{"id":"quickdraw-hour","fields":{"title":"Quickdraw Hour","typ":"Effect","raritet":"Special","body":"Alla dueller avgörs med två tärningar per spelare. Summan gäller.","antal":1}},{"id":"gold-fever","fields":{"title":"Gold Fever","typ":"Effect","raritet":"Special","body":"Varje gång en spelare delar ut 5 klunkar eller mer får den 1 guld.","antal":1}},{"id":"steady-hand","fields":{"title":"Steady Hand","typ":"Shopcard","raritet":"Koppar","body":"Slå om en tärning – din egen eller någon annans.","antal":2}}]}

